import pathlib,json,datetime
p=pathlib.Path(__file__).resolve().parent.parent;inv=json.loads((p/'inventory.json').read_text());out=[]
for i,q in enumerate(inv['projects']):
 d=p/q['full_name'].replace('/','--');mf=d/'metadata.json';rf=d/'review.json';m=json.loads(mf.read_text()) if mf.exists() else {};r=json.loads(rf.read_text()) if rf.exists() else {};entry_value=m.get('official_entry');entry=entry_value if isinstance(entry_value,dict) else {'url':entry_value,'kind':m.get('entry_label')} if isinstance(entry_value,str) else {};stars=m.get('stars');ts=m.get('stars_fetched_at') or (m.get('fetched_at') if stars is not None else None);updated=m.get('code_pushed_at') or m.get('pushed_at');lic=m.get('license_spdx'); name=q.get('name');url=entry.get('url');label=entry.get('kind');z=d/'README.zh-CN.md';en=d/'README.en.md';repo=m.get('canonical_repository') or m.get('canonical_full_name') or m.get('repository') or q['full_name'];gh=m.get('github_url') or m.get('repository_url') or ('https://github.com/'+repo);row={'original_key':q['full_name'],'repo':repo,'name':name,'summary_zh':m.get('plain_summary') or m.get('summary_zh') or m.get('description_zh') or q.get('summary') or None,'icon_source_url':(m.get('icon_source_url') if m.get('icon_basis') else (m.get('icon_source_url') or q.get('icon_source_url') or None)),'icon_license':m.get('icon_license') or None,'icon_attribution':m.get('icon_attribution') or None,'primary_url':url,'primary_label':label,'github_url':gh,'stars':stars,'stars_fetched_at':ts,'code_updated_at':updated,'code_updated_basis':(m.get('pushed_at_basis') or 'GitHub repository pushed_at') if updated else None,'license':lic if lic not in ('NOASSERTION','NONE','OTHER') else None,'documentation_license':m.get('documentation_license') or None,'platforms':m.get('platforms') if isinstance(m.get('platforms'),list) else [],'readme_zh_path':str(z.relative_to(p)) if z.exists() else None,'readme_en_path':str(en.relative_to(p)) if en.exists() else None,'status':r.get('status','pending'),'github_archived':m.get('archived'),'github_fork':m.get('fork'),'upstream_maintenance_notice':m.get('upstream_maintenance_notice'),'category':q.get('category'),'related_categories':q.get('related_categories') or [],'tags':q.get('tags') or [],'collections':[c['key'] for c in inv['collections'] if q['full_name'].lower() in [v.lower() for v in c.get('projects',[])]],'field_notes':[]};
 if not url or not label: row['field_notes'].append('主入口及类型尚未核定，留空；GitHub 链接单独保留')
 if not row['icon_source_url']:row['field_notes'].append('项目图标尚未核定，留空')
 if not row['license']:row['field_notes'].append('许可尚未核定，留空')
 if not row['platforms']:row['field_notes'].append('运行平台尚未核定，留空')
 if row['status']!='ready_for_review' and (z.exists() or en.exists()):row['field_notes'].append('正文文件仍处于未完成状态，不能当成完成稿')
 out.append(row)
result={'inventory_source':'inventory.json','revision':inv['revision'],'updated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'total':len(out),'description':'项目卡片待审清单；null/空数组表示尚未核定。摘要来自已有项目用途摘要或新核对摘要；不使用旧标题。','cards':out};tmp=p/'.card-manifest.json.tmp';tmp.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');tmp.replace(p/'card-manifest.json');print('cards',len(out),'primary confirmed',sum(bool(x['primary_url'] and x['primary_label']) for x in out),'ready',sum(x['status']=='ready_for_review' for x in out))
